def render_html(text: str) -> None:
    st.markdown(text, unsafe_allow_html=True)

def open_panel(title: str, kicker: str = "", copy: str | None = None) -> None:
    render_html(
        f"""
        <div class='mc-panel'>
            <div class='mc-panel-title-row'>
                <div>
                    <div class='mc-panel-title'>{title}</div>
                    {f"<div class='mc-panel-kicker'>{kicker}</div>" if kicker else ""}
                </div>
            </div>
            {f"<div class='mc-panel-copy'>{copy}</div>" if copy else ""}
        """
    )

def close_panel() -> None:
    render_html("</div>")

def chip(text: str, color: str = "blue") -> str:
    return f"<span class='mc-chip {color}'>{text}</span>"

def badge_for_score(score: int) -> str:
    if score >= 85:
        return chip(f"{score} • High Conviction", "green")
    if score >= 75:
        return chip(f"{score} • Actionable", "blue")
    if score >= 65:
        return chip(f"{score} • Watch", "yellow")
    return chip(f"{score} • Pass", "gray")

def bias_chip(bias: str) -> str:
    mapping = {"Bullish": "green", "Neutral": "gray", "Bearish": "red"}
    return chip(bias, mapping.get(bias, "blue"))

def trend_chip(trend: str) -> str:
    mapping = {"Bullish": "green", "Neutral": "gray", "Bearish": "red", "Improving": "blue"}
    return chip(trend, mapping.get(trend, "blue"))

def fit_class(status: str) -> Tuple[str, str]:
    s = status.lower()
    if any(x in s for x in ["bullish", "pass", "strong", "good", "excellent", "inside lower", "support", "constructive", "elevated enough", "fit"]):
        return "green", "Bullish / supportive"
    if any(x in s for x in ["neutral", "mixed", "stable", "average", "middle"]):
        return "gray", "Neutral"
    return "red", "Bearish / weak"

def render_table(df: pd.DataFrame, mode: str = "default", return_html: bool = False) -> None:
    head = "".join(f"<th>{col}</th>" for col in df.columns)
    rows = []
    for _, row in df.iterrows():
        cells = []
        for idx, col in enumerate(df.columns):
            val = row[col]
            cell = str(val)
            if col == "Bias":
                cell = bias_chip(str(val))
            elif col == "Trend":
                cell = trend_chip(str(val))
            elif col == "Score":
                cell = str(val) if str(val).startswith("<") else badge_for_score(int(val))
            elif idx == 0:
                cell = f"<span class='mc-row-strong'>{val}</span>"
            elif col in {"Status", "Read"}:
                klass, _ = fit_class(str(val))
                cell = chip(str(val), klass if klass != "gray" else "gray")
            cells.append(f"<td>{cell}</td>")
        rows.append("<tr>" + "".join(cells) + "</tr>")
    table_html = f"<table class='mc-table'><thead><tr>{head}</tr></thead><tbody>{''.join(rows)}</tbody></table>"
    if return_html:
        return table_html
    render_html(table_html)


def metric_label_with_info(label: str, help_text: str) -> str:
    safe_label = html.escape(label)
    safe_help = html.escape(help_text)
    return (
        f"<div class='mc-metric-label'>{safe_label} "
        f"<span class='mc-info-dot' title='{safe_help}'>i</span></div>"
    )

def render_metric(label: str, value: str, note: str = "") -> None:
    render_html(
        f"<div class='mc-metric'>"
        f"<div class='mc-metric-label'>{label}</div>"
        f"<div class='mc-metric-value'>{value}</div>"
        f"<div class='mc-metric-note'>{note}</div>"
        f"</div>"
    )

def control_header(label: str, help_text: str) -> str:
    safe_label = html.escape(label)
    safe_help = html.escape(help_text)
    return (
        f"<div class='mc-control-label'>{safe_label} "
        f"<span class='mc-info-dot' title='{safe_help}'>i</span></div>"
    )

