def price_band_for_value(price: float) -> str:
    if price < 10:
        return "Under $10"
    if price < 50:
        return "$10 to $50"
    if price < 200:
        return "$50 to $200"
    return "Over $200"

def enrich_scanner_df(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df.copy()
    work = df.copy()
    work["Market Cap"] = work["Ticker"].map(MARKET_CAP_BUCKETS).fillna("Unknown")
    work["Price Band"] = work["Price"].apply(price_band_for_value)
    # Prefer inline row data if present; fall back to TECHNICAL_SHELL
    if "RSI State" not in work.columns:
        work["RSI State"] = work["Ticker"].map(lambda t: TECHNICAL_SHELL.get(t, {}).get("RSI State", "Neutral"))
    if "MACD Timeframe" not in work.columns:
        work["MACD Timeframe"] = work["Ticker"].map(lambda t: TECHNICAL_SHELL.get(t, {}).get("MACD Timeframe", "Daily"))
    if "MACD Zero" not in work.columns:
        work["MACD Zero"] = work["Ticker"].map(lambda t: TECHNICAL_SHELL.get(t, {}).get("MACD Zero", "Above"))
    if "Bollinger" not in work.columns:
        work["Bollinger"] = work["Ticker"].map(lambda t: TECHNICAL_SHELL.get(t, {}).get("Bollinger", "Mid Band"))

    def _compute_strike(row):
        price = float(row["Price"])
        delta = float(row.get("Delta", 0.25))
        strat = row["Strategy"]
        if price < 20:   step = 0.5
        elif price < 50:  step = 1
        elif price < 200: step = 2.5
        else:             step = 5
        if strat in ("Covered Call", "Buy-Write"):
            raw = price + price * max(0, 0.30 - delta) * 0.9
        elif strat == "Cash-Secured Put":
            raw = price - price * max(0, 0.30 - delta) * 0.9
        elif strat == "Credit Spread":
            raw = price - price * max(0, 0.25 - delta) * 0.8
        elif strat in ("Buy Call", "LEAPS"):
            raw = price * (1 + max(0, delta - 0.40) * 0.5 + 0.01)
        elif strat == "Buy Put":
            raw = price * (1 - max(0, delta - 0.40) * 0.5 - 0.01)
        else:
            return "—"
        val = round(raw / step) * step
        return f"${val:,.0f}" if val >= 10 else f"${val:.1f}"

    work["Strike"] = work.apply(_compute_strike, axis=1)
    return work


def conviction_label(score: int) -> str:
    """Return a plain-English conviction tier for a strategy-fit score."""
    if score >= 90:
        return "Elite"
    if score >= 80:
        return "Strong"
    if score >= 70:
        return "Solid"
    if score >= 60:
        return "Moderate"
    return "Developing"


def filter_scanner(strategy: str, min_score: int, max_delta: float, min_confluence: int, biases: List[str], liquidity_choices: List[str], max_dte: int) -> pd.DataFrame:
    df = pd.DataFrame(SCANNER_ROWS)
    if strategy != "All":
        df = df[df["Strategy"] == strategy]
    if biases:
        df = df[df["Bias"].isin(biases)]
    if liquidity_choices:
        df = df[df["Liquidity"].isin(liquidity_choices)]
    df = df[(df["Score"] >= min_score) & (df["Delta"] <= max_delta) & (df["Confluence"] >= min_confluence) & (df["DTE"] <= max_dte)]
    df = df.sort_values(["Score", "Confluence", "Premium"], ascending=[False, False, False]).reset_index(drop=True)
    return enrich_scanner_df(df)

