def analyze_matrix(ticker: str) -> pd.DataFrame:
    row = next((r for r in SCANNER_ROWS if r["Ticker"] == ticker), None)
    sector = TICKER_FACTS.get(ticker, {}).get("Sector", "Unknown")
    if row:
        trend = row["Trend"]
        bias = row["Bias"]
        liquidity = row["Liquidity"]
        premium_quality = "Good" if row["Premium"] >= 1 else "Average"
        d = row["Delta"]
        weekly_macd = "Bullish" if trend == "Bullish" else "Neutral"
        daily_macd = "Bullish" if row["Score"] >= 80 else "Neutral"
        hourly_rsi = "Constructive" if bias == "Bullish" else "Neutral"
        five_min = "Pass" if row["Strategy"] in ("Covered Call", "Cash-Secured Put") else "Neutral"
        bb = "Support zone" if bias == "Bullish" else "Middle band"
        confluence = f"{row['Confluence']} / 10"
    else:
        seed = sum(ord(c) for c in ticker)
        liquidity = "Good" if seed % 2 else "Average"
        premium_quality = "Good" if seed % 3 else "Average"
        weekly_macd = "Bullish" if seed % 4 else "Neutral"
        daily_macd = "Bullish" if seed % 5 else "Neutral"
        hourly_rsi = "Constructive" if seed % 2 else "Mixed"
        five_min = "Neutral"
        bb = "Middle band"
        confluence = f"{5 + seed % 4} / 10"
        trend = "Bullish" if seed % 3 else "Neutral"
    return pd.DataFrame([
        ["Weekly MACD", weekly_macd, "Big picture trend filter"],
        ["Daily MACD", daily_macd, "Current momentum posture"],
        ["Hourly RSI / trend", hourly_rsi, "Swing rhythm and exhaustion check"],
        ["5-minute confirmation", five_min, "Most important for CC & CSP entry timing"],
        ["Bollinger position", bb, "Where price sits within the range"],
        ["Liquidity", liquidity, "Can you realistically get in and out?"],
        ["Premium quality", premium_quality, "Does the option premium justify the risk?"],
        ["Confluence", confluence, "How many things line up together?"],
        ["Sector", sector, "Context, not a trigger by itself"],
        ["Trend posture", trend, "Directional read"],
    ], columns=["Factor", "Status", "Commentary"])

def color_word(word: str) -> str:
    s = word.lower()
    if s == "bullish":
        return "<span class='mc-colored-bullish'>Bullish</span>"
    if s == "neutral":
        return "<span class='mc-colored-neutral'>Neutral</span>"
    if s == "bearish":
        return "<span class='mc-colored-bearish'>Bearish</span>"
    return f"<span class='mc-colored-blue'>{word}</span>"

def radar_response(prompt: str, active_ticker: str, focus: str) -> str:
    p = prompt.lower().strip()
    if not p:
        return "RADAR is ready. Ask about the scanner, a ticker, or how to use one of the strategy sections."
    if "assignment" in p:
        return f"Assignment risk matters most when the short strike is at a level you would not want to own. {active_ticker.upper()} should only be a short-put candidate if you genuinely want shares there."
    if "stronger" in p or "improve" in p:
        return "A stronger candidate usually needs cleaner support, enough premium for the risk, no event landmine, and confirmation that matches the strategy. CC & CSP especially wants clean short-term confirmation, not just a nice weekly chart."
    if "which strategy" in p or "best" in p:
        scores = scorecard_for_ticker(active_ticker)
        best_name = recommendation(scores)
        return f"For {active_ticker.upper()}, the best current fit in this prototype is {best_name}. If that does not match your plan, check whether the timeframe, premium quality, and assignment comfort agree with your intent."
    if "plain english" in p or "explain" in p:
        return f"In plain English: {active_ticker.upper()} looks best for {focus} if the chart, premium, and comfort level all agree. The score is not the trade. The score is only a fast filter."
    return "RADAR reads this platform as scanner first, scorecard second, and education right beside it. Use Scanner to surface names, Analyze to test a ticker, Learn to understand the why, and DELTA to map the payoff."

